import{_ as e,c as t,o as s,af as p}from"./chunks/framework.BKeRpnBD.js";const h=JSON.parse('{"title":"巽下乾上 姤：","description":"京氏易传 - 巽下乾上 姤：","frontmatter":{"title":"巽下乾上 姤：","description":"京氏易传 - 巽下乾上 姤："},"headers":[],"relativePath":"zh/classics/jingshi/003.md","filePath":"zh/classics/jingshi/003.md"}'),i={name:"zh/classics/jingshi/003.md"};function r(n,a,c,_,o,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="巽下乾上-姤" tabindex="-1">巽下乾上 姤： <a class="header-anchor" href="#巽下乾上-姤" aria-label="Permalink to “巽下乾上 姤：”">​</a></h1><p>阴爻用事。金木互体，天下风行曰姤。姤，遇也。《易》曰：“阴遇阳。”【一阴初生，阳气犹盛，阴未为敌。】与巽为飞伏，元士居世。【辛丑土，甲子水。】尊就卑，【子孙与父母相代位。】定吉凶，只取一爻之象。【多以少为贵。】九四诸侯坚刚在上，阴气处下。《易》云：“系于金柅。”</p><p>巽积阴入阳，辛壬降内外象，建庚午至乙亥。【芒种，小雪。】积算起乙亥水，至丙戌土，（虎易注：丙戌土疑为甲戌土之误。）周而复始。【灾福之兆，生乎五行升降也。】</p><p>五星从位起太白，【太白在西，居金位。】井宿从位入辛丑，【辛丑入土，元土临母也。】（虎易注：元土当为元士之误。）</p><p>建午起坤宫初六爻。《易》云：“履霜坚冰至。”建亥，龙战于野。【戌亥是乾之位。乾伏本位必战，积阴之地犹盛，故战。】</p><p>配于人事：为腹，为母，【坤顺，容于物。】于类为马。《易》云：“行地无疆。”【此释一爻配坤象，本体是乾巽，今赞一爻起阴，假坤象言之。】</p><p>内巽为风，乾为天；天下有风行，君子以号令告四方。【巽，入也。风入于坤，皆动也。故知天下有风动其物也。】</p><p>天风气象三十六候。【三十六候节气，降大风象。】木入金为始，【金纳木也。】阴不能制于阳，附于金柅。《易》之“柔道牵”也。</p><p>五行升降，以时消息，阴荡降入遁。【天山遁卦。】</p>',9)])])}const f=e(i,[["render",r]]);export{h as __pageData,f as default};
